changeText.addEventListener("click", function() {
    para.textContent = textFlag ? newPara : oldPara;
    textFlag = !textFlag;
});

changeMode.addEventListener("click",function () {
    if(btnFlag == true) {
        body.style.backgroundColor = "black"
        textContent.style.backgroundColor = "#F0F7EE"
        textContent.style.color = "black"
        textContent.style.borderColor = "red"
        changeMode.style.backgroundColor = "white"
        changeMode.style.color = "#04395f"
        changeText.style.backgroundColor = "white"
        changeText.style.color = "#04395f"
        btnFlag = false
    }
    else {
        body.style.backgroundColor = "white"
        textContent.style.backgroundColor = "#776871"
        textContent.style.color = "white"
        textContent.style.borderColor = "black"
        changeMode.style.backgroundColor = "#04395f"
        changeMode.style.color = "white"
        changeText.style.backgroundColor = "#04395f"
        changeText.style.color = "white"
        btnFlag = true
    }
})